use crate::effects::{Frame,Params};use crate::keyframe::Prop;
#[test]fn transfer_error(){let mut dec=0f64;let mut enc=0f64;for i in 0..=1000000{let x=-16.+32.*i as f32/1000000.;dec=dec.max((super::fast_transfer::decode(x)-super::managed::decode(1,x as f64,100.)).abs());let x=x as f64;enc=enc.max((super::fast_transfer::encode(x)-super::managed::encode(1,x,100.)).abs());}println!("TRANSFER decode{dec} encode{enc}");assert!(dec<0.0000003&&enc<0.000002);}
fn run(w:usize,h:usize,real:bool){let mut f=Frame::new(w,h);if real{let b=std::fs::read("/tmp/perf1080.rgba").unwrap();assert_eq!(b.len(),f.d.len());f.d=b.iter().map(|v|*v as f32/255.).collect();}else{for (i,c) in f.d.chunks_exact_mut(4).enumerate(){let v=i as f32/(w*h) as f32;c.copy_from_slice(&[v,1.-v,v*0.2+0.1,1.]);}}
for kind in [0,1]{let p=Params::new();let mut times=[Vec::new(),Vec::new()];let mut max=0f64;for _ in 0..3{let mut a=Frame{w,h,d:f.d.clone()};let now=std::time::Instant::now();if kind==0{super::finish_reference::apply(&p,&mut a,0.,42).unwrap()}else{super::printstock_reference::apply(&p,&mut a,0.).unwrap()}times[0].push(now.elapsed().as_secs_f64());let mut b=Frame{w,h,d:f.d.clone()};let now=std::time::Instant::now();if kind==0{super::finish::apply(&p,&mut b,0.,42).unwrap()}else{super::printstock::apply(&p,&mut b,0.).unwrap()}times[1].push(now.elapsed().as_secs_f64());if real{std::fs::write(format!("/tmp/fast-kind{kind}-old.f32"),a.d.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();std::fs::write(format!("/tmp/fast-kind{kind}-new.f32"),b.d.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();}max=max.max(a.d.iter().zip(&b.d).map(|(a,b)|(*a as f64-*b as f64).abs()).fold(0.,f64::max));}times.iter_mut().for_each(|v|v.sort_by(f64::total_cmp));println!("BENCH kind{kind} {w}x{h} real{real}: old{} new{} speed{} max{max}",times[0][1],times[1][1],times[0][1]/times[1][1]);assert!(max<0.00001);}}
#[test]fn effect_errors(){run(256,256,false);}
#[test]#[ignore]fn bench(){run(1920,1080,true);}
#[test]fn print_grid_error(){let mut max=0f64;for stock in 0..3{for pivot in [0.05,0.435,0.95]{for points in [-12.,0.,12.]{let mut p=Params::new();for(k,v)in[("stock",stock as f64),("pivot",pivot),("print_light",points)]{p.insert(k.into(),Prop::new(v));}let mut a=Frame::new(10001,1);for(i,c)in a.d.chunks_exact_mut(4).enumerate(){let v=-16.+32.*i as f32/10000.;c.copy_from_slice(&[v,v,v,1.]);}let mut b=Frame{w:a.w,h:1,d:a.d.clone()};super::printstock_reference::apply(&p,&mut a,0.).unwrap();super::printstock::apply(&p,&mut b,0.).unwrap();max=max.max(a.d.iter().zip(&b.d).map(|(a,b)|(*a as f64-*b as f64).abs()).fold(0.,f64::max));}}}println!("PRINT GRID max{max}");assert!(max<0.000001);}
#[test]fn finish_extremes_error(){let mut worst=0f64;for (bloom,halo) in [(0.,0.),(1.,1.),(0.,1.),(1.,0.)]{let mut p=Params::new();for(k,v)in[("bloom",bloom),("halation",halo),("threshold",0.),("knee",0.001),("grain",0.25),("vignette",1.),("radius",0.25)]{p.insert(k.into(),Prop::new(v));}let mut a=Frame::new(256,64);for(i,c)in a.d.chunks_exact_mut(4).enumerate(){let v=-4.+8.*i as f32/16384.;c.copy_from_slice(&[v,v*0.2,1.-v,if i%3==0{0.}else{0.5}]);}let mut b=Frame{w:a.w,h:a.h,d:a.d.clone()};let mut d=Frame{w:a.w,h:a.h,d:a.d.clone()};super::finish_reference::apply(&p,&mut a,0.,42).unwrap();super::finish::apply(&p,&mut b,0.,42).unwrap();super::finish::apply(&p,&mut d,0.,42).unwrap();assert_eq!(b.d,d.d);worst=worst.max(a.d.iter().zip(&b.d).map(|(a,b)|(*a as f64-*b as f64).abs()).fold(0.,f64::max));}println!("FINISH EXTREMES max{worst}");assert!(worst<0.00001);}
